//  Convert YYYY-MM-DD → DD/MM/YYYY
function formatDate(isoDate) {
  if (!isoDate) return "";
  const [year, month, day] = isoDate.split("-");
  return `${day}/${month}/${year}`;
}

//  Extract unique dates
const allDates = [...new Set(data.map(d => d.Date.split('T')[0]))].sort();

//  Group by employee
const grouped = {};
data.forEach(d => {
  const key = `${d.EmployeeName}|${d.Designation}`;
  if (!grouped[key]) {
    grouped[key] = {
      EmployeeName: d.EmployeeName,
      Designation: d.Designation,
    };
    allDates.forEach(date => {
      const formattedDate = formatDate(date);
      grouped[key][formattedDate] = '';
    });
  }

  const hours = Number.isFinite(d.Hrs) ? Math.round(d.Hrs) : 0;
  const formattedDate = formatDate(d.Date.split('T')[0]);
  grouped[key][formattedDate] = hours;
});

//  Add Total Logged & Working Hours
Object.values(grouped).forEach(emp => {
  let totalLogged = 0;
  let workingDays = 0;

  const isTL = technicalLeads.includes((emp.EmployeeName || '').trim());

  allDates.forEach(date => {
    const val = Number(emp[formatDate(date)]) || 0;
    totalLogged += val;

    const dt = new Date(date);
    const day = dt.getDay(); // 0=Sun, 6=Sat
    const isSunday = day === 0;
    const isSaturday = day === 6;
    const isHoliday = holidays.includes(date);

    // TLs: Sat+Sun off, Others: only Sun off
    if (isTL) {
      if (!isSaturday && !isSunday && !isHoliday) workingDays++;
    } else {
      if (!isSunday && !isHoliday) workingDays++;
    }
  });

  const workingHours = workingDays * 7;

  emp["Total Logged"] = totalLogged;
  emp["Working Hours"] = workingHours;
});

//  Output grouped results
return Object.values(grouped).map(row => ({ json: row }));

//  Access nested JSON inside 'Data.Result'
const data = items[0].json?.Data?.Result || [];

//  Handle missing or empty data
if (!Array.isArray(data) || data.length === 0) {
  return [{ json: { message: "No data found in API response (Data.Result empty)" } }];
}

// ----- Predefined holidays -----
const holidays = [
  "2025-10-02", // Gandhi Jayanti
  "2025-10-20"  // Example holiday
];

// ----- Convert YYYY-MM-DD → DD/MM/YYYY -----
function formatDate(isoDate) {
  if (!isoDate) return "";
  const [year, month, day] = isoDate.split("-");
  return `${day}/${month}/${year}`;
}

// ---- STEP 1: Build a leave counter for each employee ----
const leaveCount = {};
data.forEach(d => {
  const name = d.EmployeeName?.trim() || "";
  const val = String(d.LeaveTakenYn || "").trim().toLowerCase();
  if (["1", "true", "y", "yes"].includes(val)) {
    leaveCount[name] = (leaveCount[name] || 0) + 1;
  }
});

// ---- STEP 2: Extract all unique dates ----
const allDates = [...new Set(data.map(d => d.Date.split("T")[0]))].sort();

// ---- STEP 3: Group records by employee ----
const grouped = {};
data.forEach(d => {
  const key = `${d.EmployeeName}|${d.Designation}`;
  if (!grouped[key]) {
    grouped[key] = {
      EmployeeName: d.EmployeeName,
      Designation: d.Designation,
    };
    allDates.forEach(date => {
      grouped[key][formatDate(date)] = "";
    });
  }

  const hours = Number.isFinite(d.Hrs) ? Math.round(d.Hrs) : 0;
  grouped[key][formatDate(d.Date.split("T")[0])] = hours;
});

// ---- STEP 4: Add Total Logged, Working Hours, Leave, Leave Hours, Actual Hours, Hours Not Logged & Days Not Logged ----
Object.values(grouped).forEach(emp => {
  let totalLogged = 0;
  let workingDays = 0;

  allDates.forEach(date => {
    const hrs = Number(emp[formatDate(date)]) || 0;
    totalLogged += hrs;

    const dt = new Date(date);
    const isSunday = dt.getDay() === 0;
    const isHoliday = holidays.includes(date);

    if (!isSunday && !isHoliday) {
      workingDays++;
    }
  });

  const workingHours = workingDays * 7;
  const name = emp.EmployeeName?.trim() || "";
  const leave = leaveCount[name] || 0;
  const leaveHours = leave * 8;
  const actualHours = workingHours - leaveHours;
  const hoursNotLogged = actualHours - totalLogged;
  const daysNotLogged = Math.round(hoursNotLogged / 8); //  No decimals

  emp["Total Logged"] = totalLogged;
  emp["Working Hours"] = workingHours;
  emp["Leave"] = leave;
  emp["Leave Hours"] = leaveHours;
  emp["Actual Hours"] = actualHours;
  emp["Hours Not Logged"] = hoursNotLogged;
  emp["Days Not Logged"] = daysNotLogged; //  integer value only
});

// ---- STEP 5: Return formatted output ----
return Object.values(grouped).map(row => ({ json: row }));

