// (removes hidden characters like BOM)
function normalizeKey(obj) {
  const newObj = {};
  for (const [key, value] of Object.entries(obj)) {
    const cleanKey = key.replace(/[^\x20-\x7E]/g, "");
    newObj[cleanKey] = value;
  }
  return newObj;
}

