  const name = (r.EmployeeName || '').trim();
  if (tlNames.includes(name)) {
    if (!leaveCountByName[name]) leaveCountByName[name] = 0;
    if (r.LeaveTakenYn === "1" || r.LeaveTakenYn === 1) {
      leaveCountByName[name] += 1;
    }
  }
});

// ---- Add Leave, Leave Hours, Actual Hours, Hours Not Logged, and Days Not Logged ----
